CREATE TABLE pdf_asset_slots (
 slot TINYINT UNSIGNED NOT NULL PRIMARY KEY,
 active_id BIGINT UNSIGNED NULL,
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO pdf_asset_slots(slot) VALUES(3),(4),(5),(6),(7);
CREATE TABLE pdf_asset_versions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 slot TINYINT UNSIGNED NOT NULL,
 original_name VARCHAR(255) NOT NULL,
 image_data MEDIUMBLOB NOT NULL,
 width INT NOT NULL,
 height INT NOT NULL,
 sha256 CHAR(64) NOT NULL,
 status VARCHAR(16) NOT NULL DEFAULT 'pending',
 uploaded_by BIGINT UNSIGNED NOT NULL,
 reviewed_by BIGINT UNSIGNED NULL,
 review_note VARCHAR(1000) NOT NULL DEFAULT '',
 reviewed_at DATETIME(3) NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 KEY idx_pdf_asset_slot(slot,id),
 CONSTRAINT fk_pdf_asset_slot FOREIGN KEY(slot) REFERENCES pdf_asset_slots(slot)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE pdf_asset_audits (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 slot TINYINT UNSIGNED NOT NULL,
 asset_id BIGINT UNSIGNED NOT NULL,
 admin_id BIGINT UNSIGNED NOT NULL,
 action VARCHAR(24) NOT NULL,
 previous_active_id BIGINT UNSIGNED NULL,
 note VARCHAR(1000) NOT NULL DEFAULT '',
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 KEY idx_pdf_asset_audit(asset_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
